/**
 * Pattern-match line mapper for `<model>.labels.yaml` files (#409).
 *
 * The labels.yaml is machine-generated by the backend's `save_labels`
 * (yaml.safe_dump, sort_keys=False, default_flow_style=False), so the
 * indentation and key structure are predictable:
 *
 *     node_name:
 *       element_names: [...]        # shorthand
 *       input_ports:
 *         port_name:
 *           display_name: ...
 *           element_names: [...]
 *       output_ports:
 *         "Quoted Port Name":
 *           display_name: ...
 *
 * That predictability lets a 30-line pattern walker do what would
 * otherwise require pulling in a position-aware YAML parser. If a user
 * hand-edits the file in unusual ways (comments mid-block, weird
 * indentation), the mapper may miss some entries; the cost is a
 * highlight that doesn't quite land — never corruption.
 */

export type YamlPortKind = "input" | "output" | "shorthand";

/**
 * One mapped entry. ``port: null`` means the node-level row (shorthand
 * element_names or just the node opener); ``kind: "shorthand"`` reflects
 * that. For port rows, ``kind`` is "input" or "output".
 */
export type YamlEntry = {
  line: number; // 1-based line number where this entry starts
  node: string;
  port: string | null;
  kind: YamlPortKind;
};

/**
 * Walk the YAML text and emit one entry per node opener + one per port
 * inside an input_ports/output_ports block. Quoted port names (PsyNeuLink
 * sometimes generates composite names with spaces) are unquoted before
 * being recorded so callers compare against `port.name` directly.
 */
export function parseYamlMapping(text: string): YamlEntry[] {
  const lines = text.split("\n");
  const entries: YamlEntry[] = [];
  let currentNode: string | null = null;
  let currentKind: "input" | "output" | null = null;

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (!raw.trim() || raw.trim().startsWith("#")) continue;
    // Capture leading indent + the colon-terminated key.
    const m = raw.match(/^( *)("[^"]+"|[^:#]+):\s*(.*)$/);
    if (!m) continue;
    const indent = m[1].length;
    const key = stripQuotes(m[2].trim());

    if (indent === 0) {
      // Top-level node. Records the node-level entry; entering a
      // ports sub-block (below) resets currentKind for the next pass.
      currentNode = key;
      currentKind = null;
      entries.push({ line: i + 1, node: key, port: null, kind: "shorthand" });
    } else if (indent === 2 && currentNode) {
      if (key === "input_ports") currentKind = "input";
      else if (key === "output_ports") currentKind = "output";
      else currentKind = null; // some other 2-indented field (element_names shorthand, etc.)
    } else if (indent === 4 && currentNode && currentKind) {
      entries.push({ line: i + 1, node: currentNode, port: key, kind: currentKind });
    }
    // Indents > 4 (display_name / element_names inside a port) are owned
    // by the most recent port entry — no separate record needed.
  }

  return entries;
}

function stripQuotes(s: string): string {
  if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) {
    return s.slice(1, -1);
  }
  return s;
}

/**
 * Reverse lookup: given a cursor at ``line``, return the deepest entry
 * that "owns" the line — the most-recent port entry, or the node entry
 * if no port has started yet. Returns null on empty / before-first-entry.
 */
export function findEntryAtLine(entries: YamlEntry[], line: number): YamlEntry | null {
  let best: YamlEntry | null = null;
  for (const e of entries) {
    if (e.line <= line && (!best || e.line > best.line)) best = e;
  }
  return best;
}

/**
 * Forward lookup: find the line number for a specific (node, port?) pair.
 * When ``port`` is undefined, returns the node opener line. When ``port``
 * is provided, prefers an entry whose ``kind`` matches (input/output).
 */
export function findLineFor(
  entries: YamlEntry[],
  node: string,
  port?: string,
  kind?: "input" | "output",
): number | null {
  for (const e of entries) {
    if (e.node !== node) continue;
    if (port === undefined) {
      if (e.port === null) return e.line;
    } else {
      if (e.port === port && (!kind || e.kind === kind)) return e.line;
    }
  }
  return null;
}
